SELECT Catastrophe_Name
FROM catastrophe
ORDER BY Catastrophe_Name;

SELECT COUNT(*)
FROM fire_claim
WHERE LOWER(TRIM(Fireplace)) IN ('yes', 'y', 'true', '1');

SELECT AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
WHERE Year_Built < 1970;

SELECT
    c.Claim_Identifier,
    COALESCE(SUM(
        CASE WHEN EXISTS (
            SELECT 1 FROM loss_payment lp
            WHERE lp.Claim_Amount_Identifier = ca.Claim_Amount_Identifier
        ) OR EXISTS (
            SELECT 1 FROM expense_payment ep
            WHERE ep.Claim_Amount_Identifier = ca.Claim_Amount_Identifier
        ) THEN ca.Claim_Amount ELSE 0 END
    ), 0) / NULLIF(COALESCE(SUM(
        CASE WHEN EXISTS (
            SELECT 1 FROM loss_reserve lr
            WHERE lr.Claim_Amount_Identifier = ca.Claim_Amount_Identifier
        ) OR EXISTS (
            SELECT 1 FROM expense_reserve er
            WHERE er.Claim_Amount_Identifier = ca.Claim_Amount_Identifier
        ) THEN ca.Claim_Amount ELSE 0 END
    ), 0), 0) AS paid_to_reserved_ratio
FROM claim c
LEFT JOIN claim_amount ca
    ON ca.Claim_Identifier = c.Claim_Identifier
GROUP BY c.Claim_Identifier;
